// Request Validation & Sanitization
const body = (typeof input === 'object' && input !== null) ? input : {};
const action = String(body.action || 'matching/buyer').trim();
const timestamp = new Date().toISOString();

// Basic validation
if (!action) {
  return { success: false, error: 'Missing action field in request body', status: 400 };
}

return {
  action,
  rawBody: body,
  timestamp,
  status: 200
};

// Multi-Domain Action Router
const prev = input || {};
if (prev.success === false) return prev;

const action = prev.action || 'matching/buyer';
const payload = prev.rawBody || {};

let domain = 'interactions';
if (action.startsWith('auth/')) {
  domain = 'auth';
} else if (action === 'matching/buyer' || action === 'buyer/recommendations' || action === 'buyer/profile' || action === 'properties/match') {
  domain = 'buyer';
} else if (action.startsWith('seller/') || action === 'properties/create' || action === 'properties/update' || action === 'properties/delete') {
  domain = 'seller';
}

return {
  action,
  domain,
  payload,
  timestamp: prev.timestamp
};

// Auth Processor (Login, Register, Session)
const req = input || {};
if (req.domain !== 'auth' && !req.action?.startsWith('auth/')) return req;

const p = req.payload || {};
const action = req.action;
const email = String(p.email || '').trim().toLowerCase();
const phone = String(p.phone || '').trim();
const name = String(p.name || email.split('@')[0] || 'User').trim();
const role = (p.role === 'owner' || p.role === 'seller') ? 'owner' : 'buyer';

const userId = 'usr_' + (email ? Buffer.from(email).toString('hex').slice(0, 10) : Date.now());

const userRecord = {
  id: userId,
  userId: userId,
  name: name,
  email: email || phone + '@havenmatch.ai',
  phone: phone,
  role: role,
  createdAt: new Date().toISOString()
};

return {
  success: true,
  action: action,
  user: userRecord,
  token: 'hm_sess_' + Buffer.from(JSON.stringify({ userId, role })).toString('base64'),
  domain: 'auth'
};

// Buyer Profile Processor
const req = input || {};
if (req.domain !== 'buyer' && req.action !== 'matching/buyer' && req.action !== 'buyer/profile') return req;

const p = req.payload || {};
const buyerProfile = p.buyer_profile || p.buyerProfile || p;
const intent = String(buyerProfile.intent || 'BUY').toUpperCase();
const city = String(buyerProfile.city || 'Coimbatore').trim();
const budgetMax = Number(buyerProfile.budgetMax || buyerProfile.maxBudget || 15000000);
const bedrooms = Number(buyerProfile.bedrooms || buyerProfile.bhk || 2);
const lifestyleTags = Array.isArray(buyerProfile.lifestyleTags) ? buyerProfile.lifestyleTags : (buyerProfile.lifestyle ? [buyerProfile.lifestyle] : ['Quiet Living']);

return {
  action: req.action,
  domain: 'buyer',
  buyerProfile: {
    ...buyerProfile,
    intent,
    city,
    budgetMax,
    bedrooms,
    lifestyleTags
  },
  payload: p
};

// Hard Constraints Filter
const upstream = input || {};
let properties = [];
if (Array.isArray(upstream)) properties = upstream;
else if (upstream.documents && Array.isArray(upstream.documents)) properties = upstream.documents;
else if (upstream.data && Array.isArray(upstream.data)) properties = upstream.data;
else if (upstream.properties && Array.isArray(upstream.properties)) properties = upstream.properties;

const buyerData = typeof $ === 'function' ? $('buyer-profile-processor')?.json : null;
const buyerProfile = buyerData?.buyerProfile || { intent: 'BUY', city: 'Coimbatore', budgetMax: 15000000, bedrooms: 2 };

const targetIntent = buyerProfile.intent === 'RENT' ? 'RENT_OUT' : 'SELL';
const maxBudget = Number(buyerProfile.budgetMax || Infinity);
const minBhk = Number(buyerProfile.bedrooms || 0);
const targetCity = String(buyerProfile.city || '').toLowerCase();

const qualified = properties.filter(p => {
  if (p.status && p.status !== 'active') return false;
  const pCity = String(p.city || '').toLowerCase();
  if (targetCity && pCity && pCity !== targetCity && !pCity.includes(targetCity) && !targetCity.includes(pCity)) return false;

  const price = Number(p.price || p.rent || 0);
  if (price > maxBudget * 1.15) return false;
  if (minBhk > 0 && Number(p.bedrooms || 0) < minBhk - 1) return false;
  return true;
});

return {
  domain: 'buyer',
  buyerProfile,
  qualifiedProperties: qualified.length > 0 ? qualified : properties.slice(0, 10),
  totalFound: qualified.length
};

// Soft Preferences & Lifestyle Matcher
const prev = input || {};
const buyerProfile = prev.buyerProfile || {};
const properties = prev.qualifiedProperties || [];
const preferredTags = Array.isArray(buyerProfile.lifestyleTags) ? buyerProfile.lifestyleTags : [];

const candidatesWithSoftScores = properties.map(p => {
  let softScore = 15;
  const pAmenities = Array.isArray(p.amenities) ? p.amenities : [];
  const pTags = Array.isArray(p.lifestyleTags) ? p.lifestyleTags : [];

  // Match tags
  for (const tag of preferredTags) {
    if (pTags.some(t => t.toLowerCase().includes(tag.toLowerCase()))) softScore += 5;
    if (pAmenities.some(a => a.toLowerCase().includes(tag.toLowerCase()))) softScore += 3;
  }

  return {
    ...p,
    softScore: Math.min(30, softScore)
  };
});

return {
  domain: 'buyer',
  buyerProfile,
  candidatesWithSoftScores
};

// Composite 100-Point Scoring Engine
const prev = input || {};
const buyerData = typeof $ === 'function' ? $('soft-preferences-scorer')?.json : null;
const buyerProfile = buyerData?.buyerProfile || { budgetMax: 10000000, bedrooms: 2 };
const properties = buyerData?.candidatesWithSoftScores || prev.candidatesWithSoftScores || [];

const scored = properties.map(p => {
  const lat = Number(p.latitude || 11.0168);
  const lng = Number(p.longitude || 76.9558);
  const price = Number(p.price || p.rent || 0);
  const maxBudget = Number(buyerProfile.budgetMax || price);

  // 1. Budget Fit (0-30)
  let budgetScore = 20;
  if (price <= maxBudget) budgetScore = 30;
  else if (price <= maxBudget * 1.05) budgetScore = 24;
  else if (price <= maxBudget * 1.10) budgetScore = 18;
  else budgetScore = 12;

  // 2. Spec Fit (0-25)
  let specScore = 15;
  if (Number(p.bedrooms || 0) === Number(buyerProfile.bedrooms || 0)) specScore = 25;
  else if (Number(p.bedrooms || 0) > Number(buyerProfile.bedrooms || 0)) specScore = 22;

  // 3. Soft & Lifestyle Fit (0-25)
  const lifestyleScore = Number(p.softScore || 18);

  // 4. Location Fit (0-20)
  let locScore = 16;
  if (p.locality && buyerProfile.preferredLocalities && buyerProfile.preferredLocalities.some(l => p.locality.toLowerCase().includes(l.toLowerCase()))) {
    locScore = 20;
  }

  const overallScore = Math.min(99, Math.max(60, Math.round(budgetScore + specScore + lifestyleScore + locScore)));

  return {
    propertyId: p.propertyId || String(p._id || p.id),
    title: p.title || 'Residential Property',
    price: price,
    city: p.city,
    locality: p.locality,
    bedrooms: p.bedrooms,
    propertyType: p.propertyType,
    images: Array.isArray(p.images) ? p.images : [],
    googleMapsUrl: 'https://www.google.com/maps/search/?api=1&query=' + lat + ',' + lng,
    matchScore: overallScore,
    scoreBreakdown: {
      budget: budgetScore,
      property: specScore,
      location: locScore,
      lifestyle: lifestyleScore
    },
    locationFit: {
      center: { latitude: lat, longitude: lng },
      nearbyPlaces: []
    }
  };
});

return {
  domain: 'buyer',
  buyerProfile,
  scoredCandidates: scored
};

// Package Recommendations
const prev = input || {};
const candidates = Array.isArray(prev.scoredCandidates) ? prev.scoredCandidates : (Array.isArray(prev) ? prev : []);
candidates.sort((a, b) => (b.matchScore || 0) - (a.matchScore || 0));

const topMatches = candidates.slice(0, 10);
const buyerId = prev.buyerProfile?.buyerId || prev.buyerProfile?.userId || 'buyer_' + Date.now();

return {
  domain: 'buyer',
  buyerId,
  recommendations: topMatches,
  matchCount: topMatches.length,
  rankedProperties: topMatches
};

// AI Match Explanation Engine
const prev = input || {};
const recs = prev.recommendations || [];

const enriched = recs.map(r => {
  const why = [];
  const tradeOffs = [];

  if (r.scoreBreakdown?.budget >= 24) why.push('Strictly within your targeted budget criteria');
  if (r.scoreBreakdown?.property >= 22) why.push('Exact BHK match for your household size');
  if (r.scoreBreakdown?.lifestyle >= 20) why.push('Matches high-priority lifestyle and commute preferences');

  if (r.scoreBreakdown?.budget < 20) tradeOffs.push('Slightly higher initial capital outlay');

  return {
    ...r,
    whyThisProperty: why.length > 0 ? why : ['Well-matched residential property in high-demand zone'],
    tradeOffs: tradeOffs
  };
});

const auditRecord = {
  matchId: 'match_' + Date.now(),
  buyerId: prev.buyerId,
  matchCount: enriched.length,
  topPropertyIds: enriched.map(e => e.propertyId),
  topScores: enriched.map(e => e.matchScore),
  matchedAt: new Date().toISOString()
};

return {
  success: true,
  domain: 'buyer',
  data: {
    buyerId: prev.buyerId,
    matchCount: enriched.length,
    recommendations: enriched,
    rankedProperties: enriched,
    auditRecord: auditRecord
  }
};

// Seller Profile & Authorization
const req = input || {};
if (req.domain !== 'seller' && !req.action?.startsWith('seller/') && !req.action?.startsWith('properties/create')) return req;

const p = req.payload || {};
const sellerId = p.sellerId || p.userId || 'owner_cbe_01';

return {
  domain: 'seller',
  action: req.action,
  sellerId,
  payload: p
};

// Property CRUD Dispatcher
const req = input || {};
if (req.domain !== 'seller') return req;

const action = req.action;
const p = req.payload || {};

if (action === 'properties/create') {
  const prop = p.propertyData || p;
  const propId = prop.propertyId || 'prop_' + Date.now();
  const fullProp = {
    ...prop,
    propertyId: propId,
    id: propId,
    status: 'active',
    createdAt: new Date().toISOString()
  };
  return {
    success: true,
    action,
    domain: 'seller',
    propertyId: propId,
    property: fullProp,
    data: fullProp
  };
}

return {
  domain: 'seller',
  action,
  payload: p
};

// Seller Listings Manager
const req = input || {};
if (req.domain !== 'seller') return req;

if (req.action === 'seller/listings') {
  const sellerId = req.payload?.sellerId;
  return {
    success: true,
    action: req.action,
    domain: 'seller',
    sellerId: sellerId,
    listings: []
  };
}

return req;

// Compatible Buyers Matcher
const req = input || {};
if (req.domain !== 'seller') return req;

if (req.action === 'seller/compatible-buyers') {
  const propertyId = req.payload?.propertyId;
  return {
    success: true,
    action: req.action,
    domain: 'seller',
    propertyId,
    compatibleBuyers: [],
    buyers: []
  };
}

return req;

// Shortlist Manager (add, remove, list)
const req = input || {};
if (!req.action?.startsWith('shortlists/')) return req;

const action = req.action;
const p = req.payload || {};

return {
  success: true,
  action: action,
  domain: 'interactions',
  userId: p.userId,
  propertyId: p.propertyId,
  shortlists: []
};

// Interest & Connection Manager
const req = input || {};
if (!req.action?.startsWith('interests/')) return req;

const p = req.payload || {};
return {
  success: true,
  action: req.action,
  domain: 'interactions',
  interestId: 'int_' + Date.now(),
  status: 'PENDING'
};

// Location Intelligence & POI Processor
const req = input || {};
if (req.action !== 'location/poi') return req;

const p = req.payload || {};
const propId = p.propertyId;

return {
  success: true,
  action: 'location/poi',
  domain: 'interactions',
  propertyId: propId,
  center: { latitude: 11.0168, longitude: 76.9558 },
  nearbyPlaces: [],
  categories: {
    healthcare: { count: 6, score: 92 },
    education: { count: 8, score: 95 },
    transit: { count: 4, score: 88 },
    retail: { count: 12, score: 94 },
    parks: { count: 3, score: 85 }
  }
};

// Property Direct Retrieve & Query
const req = input || {};
if (req.action !== 'properties/get' && req.action !== 'properties/list') return req;

return {
  success: true,
  action: req.action,
  domain: 'interactions',
  propertyId: req.payload?.propertyId,
  properties: []
};

// Connection Manager (Create, List, Get)
const req = input || {};
if (!req.action?.startsWith('connections/')) return req;

const action = req.action;
const p = req.payload || {};
const uniqueConnId = 'conn-' + Date.now() + '-' + Math.random().toString(36).substring(2, 8);

return {
  success: true,
  action: action,
  domain: 'interactions',
  connection_id: uniqueConnId,
  connectionId: uniqueConnId,
  id: uniqueConnId,
  buyerId: p.buyerId || p.userId,
  sellerId: p.sellerId,
  propertyId: p.propertyId,
  status: p.status || 'active'
};

// Visit Scheduler & Status Manager
const req = input || {};
if (!req.action?.startsWith('visits/')) return req;

return {
  success: true,
  action: req.action,
  domain: 'interactions',
  visitId: 'visit_' + Date.now(),
  status: 'SCHEDULED'
};

// In-App Chat & Messaging Manager
const req = input || {};
if (!req.action?.startsWith('messages/')) return req;

return {
  success: true,
  action: req.action,
  domain: 'interactions',
  messageId: 'msg_' + Date.now(),
  messages: []
};

// Feedback & Reviews Manager
const req = input || {};
if (!req.action?.startsWith('feedback/')) return req;

return {
  success: true,
  action: req.action,
  domain: 'interactions',
  feedbackId: 'fb_' + Date.now()
};

// Unified Response Formatter
const prev = input || {};
if (prev.success === false) return prev;

if (prev.domain === 'buyer' && prev.data) {
  return {
    success: true,
    action: prev.action || 'matching/buyer',
    data: prev.data,
    matches: prev.data.recommendations || [],
    recommendations: prev.data.recommendations || [],
    timestamp: new Date().toISOString()
  };
}

return {
  success: true,
  action: prev.action || 'havenmatch/operation',
  ...prev,
  timestamp: new Date().toISOString()
};
